})
export class PaymentsModule {}

// payment.processor.ts (PR excerpt)
interface PaymentJobData {
  paymentId: string
  customerId: string
  amount: number
}

@Processor("payments")
export class PaymentProcessor extends WorkerHost {
  private readonly logger = new Logger(PaymentProcessor.name)

  constructor(
    @InjectQueue("payments-dead-letter")
    private readonly deadLetterQueue: Queue,
    private readonly paymentGateway: PaymentGatewayService,
    private readonly paymentRepo: PaymentRepository,
  ) {
    super()
  }

  async process(job: Job<PaymentJobData>): Promise<void> {
    const { paymentId, customerId, amount } = job.data

    // Charge the customer through the external gateway. No idempotency key
    // is passed, and there is no "already charged?" lookup before calling it.
    await this.paymentGateway.charge(customerId, amount)

    // If the process crashes between the line above and the line below,
    // the retry re-enters this method and calls charge(...) again.
    await this.paymentRepo.markPaid(paymentId)
  }

  @OnWorkerEvent("failed")
  async onFailed(job: Job<PaymentJobData>, err: Error): Promise<void> {
    this.logger.error(
      `payment job ${job.id} failed (attempt ${job.attemptsMade}/${job.opts.attempts}): ${err.message}`,
      err.stack,
    )

    // Runs on every failed attempt, including ones where BullMQ still has
    // retries left - there is no comparison of attemptsMade against the
    // configured max attempts before writing to the dead-letter queue.
    await this.deadLetterQueue.add("failed-payment", job.data)
  }
}

// payment-gateway.service.ts (PR excerpt)
@Injectable()
export class PaymentGatewayService {
  async charge(customerId: string, amount: number): Promise<{ chargeId: string }> {
    // Calls the external payment provider directly; no idempotency key
    // (e.g. the paymentId) is sent, so a retried call charges again.
    return this.httpClient.post("/charges", { customerId, amount })
  }
}

